const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const state = { supabase:null, user:null, profile:null, page:"dashboard", students:[], payments:[], attendance:[], classes:[], work:[], pendingEmail:"", pendingName:"", otpPurpose:"register", attendanceDate:todayISO(), attendanceCalendarMonth:`${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,"0")}`, attendanceCalendarStudent:"", enterPromise:null, passwordRecovery:false, resetOtpSent:false, month:new Date().toISOString().slice(0,7) };
const configured = !CONFIG.SUPABASE_URL.includes("YOUR_PROJECT_ID") && !CONFIG.SUPABASE_ANON_KEY.includes("YOUR_SUPABASE_ANON_KEY");

function todayISO(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`}
function money(n){return new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:0}).format(Number(n||0))}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function initials(s){return String(s||"T").trim().split(/\s+/).slice(0,2).map(x=>x[0]||"").join("").toUpperCase()}
function dateLabel(v){if(!v)return "—";return new Date(v+"T00:00:00").toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"})}
function monthLabel(v){if(!v)return "—";return new Date(v+"-01T00:00:00").toLocaleDateString("en-IN",{month:"long",year:"numeric"})}
function shiftMonth(v,delta){const [y,m]=v.split("-").map(Number);const d=new Date(y,m-1+delta,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`}
function toast(msg,error=false){const el=$("#toast");el.textContent=msg;el.classList.toggle("error",error);el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),3500)}
function setBusy(btn,busy,label){if(!btn)return;btn.disabled=busy;if(busy){btn.dataset.oldText=btn.innerHTML;btn.textContent=label||"Please wait…"}else if(btn.dataset.oldText){btn.innerHTML=btn.dataset.oldText;delete btn.dataset.oldText}}
function showAuth(mode="login"){
  if(mode==="reset"){
    state.resetOtpSent=false;
    const otp=$("#resetOtpCode"); if(otp){otp.value="";otp.disabled=true}
    const verify=$("#verifyResetOtpBtn"); if(verify)verify.disabled=true;
  }
  $("#authScreen").classList.remove("hidden"); $("#appShell").classList.add("hidden");
  ["loginForm","registerForm","otpForm","resetForm","newPasswordForm"].forEach(id=>{const el=$("#"+id);if(el)el.classList.add("hidden")});
  $("#authFootnote")?.classList.remove("hidden");
  const titles={login:["Welcome back","Log in to manage your tuition."],register:["Create your account","Start managing your tuition in one place."],otp:["Verify your email","Enter the code sent to your email address."],reset:["Reset your password","Enter your email and choose a new password. We’ll send an 8-digit OTP to verify it."],newPassword:["Create a new password","Choose a strong password you can remember."]};
  const title=$("#authTitle"), subtitle=$("#authSubtitle");
  if(title)title.textContent=(titles[mode]||titles.login)[0];
  if(subtitle)subtitle.textContent=(titles[mode]||titles.login)[1];
  [["loginForm","login"],["registerForm","register"],["otpForm","otp"],["resetForm","reset"],["newPasswordForm","newPassword"]].forEach(([id,m])=>{const el=$("#"+id);if(el)el.classList.toggle("hidden",mode!==m)});
  $("#showRegisterBtn")?.classList.toggle("hidden",mode!=="login"); $(".auth-divider")?.classList.toggle("hidden",mode!=="login"); $(".auth-footnote")?.classList.toggle("hidden",mode!=="login");
}
function showApp(){ $("#authScreen").classList.add("hidden");$("#appShell").classList.remove("hidden"); }
function setupGuard(){if(state.profile && !state.profile.tuition_name){document.querySelector("#setupOverlay")?.remove();const overlay=document.createElement("div");overlay.className="setup-overlay";overlay.id="setupOverlay";overlay.innerHTML=`<form class="setup-card" id="tuitionSetupForm"><div class="brand-mark" style="margin-bottom:18px"><svg viewBox="0 0 32 32"><path d="M3 11.5 16 5l13 6.5L16 18 3 11.5Z"/><path d="M8 14.2v7.1c4.9 4 11.1 4 16 0v-7.1M29 12v9"/></svg></div><div class="eyebrow">ONE-TIME SETUP</div><h2>What’s your tuition called?</h2><p>Add your tuition name to personalise your workspace. You can change it later in Settings.</p><label for="tuitionNameInput">Tuition name</label><input id="tuitionNameInput" maxlength="120" placeholder="e.g. Bright Future Tuition" required><button class="btn btn-primary btn-large" type="submit">Save & open dashboard →</button></form>`;document.body.appendChild(overlay);$("#tuitionSetupForm").addEventListener("submit",saveTuitionName)}}
async function saveTuitionName(ev){ev.preventDefault();const name=$("#tuitionNameInput").value.trim();if(!name)return;const {error}=await state.supabase.from("teacher_profiles").upsert({id:state.user.id,email:state.user.email,full_name:state.user.user_metadata?.full_name||"",tuition_name:name,updated_at:new Date().toISOString()});if(error){toast(error.message,true);return}state.profile={...state.profile,tuition_name:name,email:state.user.email};$("#setupOverlay")?.remove();syncProfile();await loadData();renderPage()}
function syncProfile(){const name=state.profile?.tuition_name||"Your tuition";$("#sidebarTuitionName").textContent=name;$("#profileName").textContent=state.profile?.full_name||"Teacher";$("#profileAvatar").textContent=initials(state.profile?.full_name||"T");$(".tuition-avatar").textContent=initials(name)}
function readyCheck(){if(!configured){toast("Add your Supabase URL and anon key in app.js, then reload.",true);return false}return true}
async function init(){
  $("#year").textContent=new Date().getFullYear();
  $("#showRegisterBtn").addEventListener("click",()=>showAuth("register"));
  $("#showLoginBtn").addEventListener("click",()=>showAuth("login"));
  $("#cancelOtpBtn").addEventListener("click",()=>showAuth(state.otpPurpose==="reset"?"reset":"register"));
  $("#forgotBtn").addEventListener("click",()=>showAuth("reset"));
  $("#cancelResetBtn").addEventListener("click",()=>showAuth("login"));
  $$("[data-toggle-password]").forEach(b=>b.addEventListener("click",()=>{const el=$("#"+b.dataset.togglePassword);el.type=el.type==="password"?"text":"password"}));
  $("#loginForm").addEventListener("submit",login);
  $("#registerForm").addEventListener("submit",register);
  $("#otpForm").addEventListener("submit",verifyOtp);
  $("#otpCode").addEventListener("input",()=>{$("#otpCode").value=$("#otpCode").value.replace(/\D/g,"").slice(0,8)});
  $("#resendOtpBtn").addEventListener("click",resendOtp);
  $("#resetForm").addEventListener("submit",completeOtpPasswordReset);
  $("#sendResetOtpBtn").addEventListener("click",requestResetOtp);
  $("#resetOtpCode").addEventListener("input",()=>{$("#resetOtpCode").value=$("#resetOtpCode").value.replace(/\D/g,"").slice(0,8)});
  $("#logoutBtn").addEventListener("click",logout);
  $("#menuBtn").addEventListener("click",()=>toggleSidebar(true));
  $("#sidebarScrim").addEventListener("click",()=>toggleSidebar(false));
  $("#editTuitionBtn").addEventListener("click",()=>openTuitionEditor());
  $("#profileBtn").addEventListener("click",()=>navigate("settings"));
  $$(".nav-item[data-page],.mobile-nav-item[data-page]").forEach(b=>b.addEventListener("click",()=>{if(b.dataset.page==="more"){toggleSidebar(true);return}navigate(b.dataset.page)}));
  $("#modal").addEventListener("click",ev=>{if(ev.target===$("#modal"))$("#modal").close()});
  if(!configured){showAuth("login");const warn=document.createElement("div");warn.className="notice config-notice";warn.innerHTML="<strong>Setup needed:</strong> open <code>app.js</code> and add your Supabase Project URL and anon/publishable key. See <code>README.md</code>.";$(".auth-card").prepend(warn);return}
  state.supabase=window.supabase.createClient(CONFIG.SUPABASE_URL,CONFIG.SUPABASE_ANON_KEY);
  const url = new URL(window.location.href);
  const recoveryMode = url.searchParams.has("code") || url.searchParams.get("mode")==="recovery" || /type=recovery/.test(window.location.hash);
  if(url.searchParams.has("code")){
    const {error}=await state.supabase.auth.exchangeCodeForSession(url.searchParams.get("code"));
    if(error){console.error("Auth callback exchange failed",error);if(recoveryMode){toast("This reset link is invalid or expired. Request a new one.",true);showAuth("reset");return}}
  }
  const {data:{session}}=await state.supabase.auth.getSession();
  const recoveryHash = /type=recovery/.test(window.location.hash) || /access_token=/.test(window.location.hash) && /type=recovery/.test(window.location.hash);
  if(recoveryMode || recoveryHash){
    if(session){state.passwordRecovery=true;state.user=session.user;showAuth("newPassword");setRecoveryEmail(session.user.email)}
    else {toast("Reset link is invalid or expired. Please request a new password reset email.",true);showAuth("reset")}
  } else if(session){state.user=session.user;await enterApp()}else showAuth("login");
  state.supabase.auth.onAuthStateChange(async(event,session)=>{
    if(event==="PASSWORD_RECOVERY") { state.passwordRecovery=true; if(session) state.user=session.user; showAuth("newPassword"); setRecoveryEmail(session?.user?.email); return; }
    if(state.passwordRecovery && session){state.user=session.user;showAuth("newPassword");setRecoveryEmail(session.user.email);return;}
    if(session && (!state.user || state.user.id!==session.user.id)){state.user=session.user;await enterApp()}
    else if(!session&&state.user){state.user=null;state.profile=null;showAuth("login")}
  });
}
async function login(ev){ev.preventDefault();if(!readyCheck())return;const email=$("#loginEmail").value.trim().toLowerCase(),password=$("#loginPassword").value;if(!email){toast("Enter your email address.",true);return}const btn=$("#loginBtn");setBusy(btn,true,"Logging in…");try{const {data,error}=await state.supabase.auth.signInWithPassword({email,password});if(error)throw error;state.user=data.user;await enterApp()}catch(e){toast(authError(e),true)}finally{setBusy(btn,false)}}
async function register(ev){ev.preventDefault();if(!readyCheck())return;const name=$("#regName").value.trim(),email=$("#regEmail").value.trim().toLowerCase(),password=$("#regPassword").value;if(!name){toast("Enter your name.",true);return}if(!email){toast("Enter a valid email address.",true);return}if(password.length<8){toast("Use a password with at least 8 characters.",true);return}state.pendingEmail=email;state.pendingName=name;state.otpPurpose="register";const btn=$("#registerBtn");setBusy(btn,true,"Sending verification email…");try{const {data,error}=await state.supabase.auth.signUp({email,password,options:{data:{full_name:name}}});if(error)throw error;if(data.session){state.user=data.user;await enterApp();return}showAuth("otp");$("#otpHelp").textContent=`Enter the verification code sent to ${email}.`;toast("Verification email requested. Check your inbox and spam folder.")}catch(e){toast(authError(e),true)}finally{setBusy(btn,false)}}
async function verifyOtp(ev){ev.preventDefault();const token=$("#otpCode").value.trim();if(!/^\d{8}$/.test(token)){toast("Enter the complete 8-digit verification code.",true);return}const btn=$("#verifyOtpBtn");setBusy(btn,true,"Verifying…");try{const {data,error}=await state.supabase.auth.verifyOtp({email:state.pendingEmail,token,type:"signup"});if(error)throw error;state.user=data.user;await enterApp()}catch(e){toast(authError(e),true)}finally{setBusy(btn,false)}}
async function resendOtp(){try{const {error}=await state.supabase.auth.resend({type:"signup",email:state.pendingEmail});if(error)throw error;toast("A new verification email has been requested.")}catch(e){toast(authError(e),true)}}
function setRecoveryEmail(email){const field=$("#recoveryEmail");if(field)field.value=email||""}
async function requestResetOtp(ev){ev.preventDefault();if(!readyCheck())return;const email=$("#resetEmail").value.trim().toLowerCase(),password=$("#newPassword").value,confirm=$("#confirmNewPassword").value;if(!email){toast("Enter your registered email address.",true);return}if(password.length<8){toast("Use a password with at least 8 characters.",true);return}if(password!==confirm){toast("New password and confirm password do not match.",true);$("#confirmNewPassword").focus();return}const btn=$("#sendResetOtpBtn");setBusy(btn,true,"Sending OTP…");try{const {error}=await state.supabase.auth.resetPasswordForEmail(email);if(error)throw error;state.pendingEmail=email;state.resetOtpSent=true;$("#resetOtpCode").disabled=false;$("#verifyResetOtpBtn").disabled=false;toast("Password reset OTP sent. Check your email and spam folder.")}catch(e){toast(authError(e),true)}finally{setBusy(btn,false)}}
async function completeOtpPasswordReset(ev){ev.preventDefault();if(!readyCheck())return;const email=$("#resetEmail").value.trim().toLowerCase(),password=$("#newPassword").value,confirm=$("#confirmNewPassword").value,token=$("#resetOtpCode").value.trim();if(!state.resetOtpSent){toast("First tap Send OTP and check your email.",true);return}if(!/^\d{8}$/.test(token)){toast("Enter the complete 8-digit OTP from your email.",true);return}if(password.length<8){toast("Use at least 8 characters.",true);return}if(password!==confirm){toast("New password and confirm password do not match.",true);$("#confirmNewPassword").focus();return}const btn=$("#verifyResetOtpBtn");setBusy(btn,true,"Verifying OTP…");try{const {data,error}=await state.supabase.auth.verifyOtp({email,token,type:"recovery"});if(error)throw error;state.passwordRecovery=true;state.user=data.user;const {error:updateError}=await state.supabase.auth.updateUser({password});if(updateError)throw updateError;await state.supabase.auth.signOut();state.user=null;state.profile=null;state.passwordRecovery=false;state.resetOtpSent=false;history.replaceState(null,"",window.location.pathname);showAuth("login");$("#loginEmail").value=email;$("#loginPassword").value="";$("#newPassword").value="";$("#confirmNewPassword").value="";$("#resetOtpCode").value="";window.alert("Password reset successful! Please log in with your new password.")}catch(e){toast(authError(e),true)}finally{setBusy(btn,false)}}
function authError(e){const m=String(e?.message||"Something went wrong.");if(/already registered|already exists|user already/i.test(m))return "This email may already have an account. Please log in instead.";if(/invalid login credentials/i.test(m))return "Incorrect email address or password.";if(/rate limit/i.test(m))return "Too many attempts. Please wait before trying again.";if(/email rate limit|email.*rate/i.test(m))return "Email sending limit reached. Configure a custom SMTP provider in Supabase and try again later.";return m}
async function enterApp(){if(!state.user)return;if(state.enterPromise)return state.enterPromise;state.enterPromise=(async()=>{showApp();const {data,error}=await state.supabase.from("teacher_profiles").select("*").eq("id",state.user.id).maybeSingle();if(error){toast("Profile load failed: "+error.message,true);return}state.profile=data||{id:state.user.id,email:state.user.email,full_name:state.user.user_metadata?.full_name||"",tuition_name:null};if(!data){const {error:insertError}=await state.supabase.from("teacher_profiles").upsert({id:state.user.id,email:state.user.email,full_name:state.user.user_metadata?.full_name||""},{onConflict:"id"});if(insertError){toast(insertError.message,true)}}syncProfile();if(!state.profile.tuition_name){setupGuard();return}document.querySelector("#setupOverlay")?.remove();await loadData();renderPage()})();try{return await state.enterPromise}finally{state.enterPromise=null}}
async function loadAllRows(table){const pageSize=1000;let from=0,all=[];while(true){const {data,error}=await state.supabase.from(table).select("*").order("created_at",{ascending:false}).range(from,from+pageSize-1);if(error)throw error;const rows=data||[];all=all.concat(rows);if(rows.length<pageSize)break;from+=pageSize}return all}
async function loadData(){if(!state.supabase||!state.user)return;const tables=[["students","students"],["payments","fee_payments"],["attendance","attendance_records"],["classes","classes"],["work","work_items"]];const results=await Promise.all(tables.map(async([key,table])=>{try{return {key,table,data:await loadAllRows(table)}}catch(error){return {key,table,error}}}));const failures=[];for(const r of results){if(r.error){console.error(r.table,r.error);failures.push(`${r.table}: ${r.error.message}`)}else state[r.key]=r.data}if(failures.length)toast("Some records could not be loaded. Check Supabase schema/RLS: "+failures.join("; "),true)}
async function refresh(){await loadData();renderPage()}
function toggleSidebar(open){$("#sidebar").classList.toggle("open",open);$("#sidebarScrim").classList.toggle("show",open)}
function navigate(page){if(page==="more"){toggleSidebar(true);return}state.page=page;toggleSidebar(false);renderPage();window.scrollTo({top:0,behavior:"smooth"})}
function setActiveNav(page){$$("[data-page]").forEach(b=>b.classList.toggle("active",b.dataset.page===page||(page==="settings"&&b.dataset.page==="more")))}
function pageHeader(title,subtitle,actions=""){return `<div class="page-title-row"><div><h1 class="page-title">${title}</h1><p class="page-subtitle">${subtitle}</p></div><div class="page-actions">${actions}</div></div>`}
function btn(label,action,primary=true,icon=""){return `<button class="btn ${primary?"btn-primary":"btn-outline"}" data-action="${action}">${icon?`<span>${icon}</span>`:""}${label}</button>`}
function stat(label,value,icon,note="",tone=""){return `<div class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ${tone}">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function empty(title,desc,action,label){return `<div class="empty-state"><div class="empty-icon">✦</div><strong>${title}</strong><p>${desc}</p>${action?btn(label,action,true):""}</div>`}
function initialsAvatar(name){return `<span class="person-avatar">${esc(initials(name))}</span>`}
function studentName(id){return state.students.find(s=>s.id===id)?.full_name||"Deleted student"}
function paymentTotal(rows){return rows.reduce((sum,r)=>sum+Number(r.amount||0),0)}
function monthlyPayments(){return state.payments.filter(p=>(p.paid_on||p.created_at||"").slice(0,7)===state.month)}
function studentDue(s){const paid=state.payments.filter(p=>p.student_id===s.id&&p.fee_month===state.month).reduce((n,p)=>n+Number(p.amount||0),0);return Math.max(0,Number(s.monthly_fee||0)-paid)}
function renderPage(){if(!state.user||!state.profile?.tuition_name)return;syncProfile();const titles={dashboard:"Dashboard",students:"Students",attendance:"Attendance",fees:"Fees & Payments",classes:"Classes & Timetable",work:"Homework & Tests",reports:"Reports",settings:"Settings"};$("#pageCrumb").textContent=titles[state.page]||"Dashboard";setActiveNav(state.page);const renderers={dashboard:renderDashboard,students:renderStudents,attendance:renderAttendance,fees:renderFees,classes:renderClasses,work:renderWork,reports:renderReports,settings:renderSettings};$("#pageContent").innerHTML=(renderers[state.page]||renderDashboard)();wirePageActions()}
function renderCollectionTrend(){const now=new Date();const months=[];for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;const amount=state.payments.filter(p=>(p.paid_on||p.created_at||"").slice(0,7)===key).reduce((sum,p)=>sum+Number(p.amount||0),0);months.push({key,label:d.toLocaleDateString("en-IN",{month:"short"}),amount})}const max=Math.max(1,...months.map(m=>m.amount));const total=months.reduce((sum,m)=>sum+m.amount,0);return `<section class="collection-trend"><div class="collection-trend-head"><div><h2>Fee collection trend</h2><p>Recorded payments over the last six months</p></div><div class="collection-trend-total">${money(total)}</div></div><div class="trend-bars" role="img" aria-label="Fee collection for the last six months">${months.map(m=>`<div class="trend-month" title="${esc(m.label)}: ${money(m.amount)}"><div class="trend-bar-wrap"><div class="trend-bar" style="height:${m.amount?Math.max(5,Math.round(m.amount/max*100)):3}%"></div></div><strong>${m.amount?money(m.amount):"—"}</strong><small>${m.label}</small></div>`).join("")}</div></section>`}
function renderDashboard(){const month=monthlyPayments(),collected=paymentTotal(month),pending=state.students.reduce((n,s)=>n+studentDue(s),0),present=state.attendance.filter(a=>a.attendance_date===todayISO()&&a.status==="present").length;const recent=state.payments.slice(0,5);return `${pageHeader(`Good ${new Date().getHours()<12?"morning":new Date().getHours()<17?"afternoon":"evening"}, ${esc(state.profile.full_name?.split(" ")[0]||"Teacher")} 👋`,`Here’s what’s happening at ${esc(state.profile.tuition_name)} today.`,btn("＋ Add student","add-student"))}<div class="stats-grid">${stat("TOTAL STUDENTS",state.students.length,"♙","Across all classes")}${stat("PRESENT TODAY",present,"✓","Attendance marked today","green")}${stat("FEES COLLECTED",money(collected),"₹",monthLabel(state.month),"purple")}${stat("FEES PENDING",money(pending),"↗","Current month","amber")}</div>${renderCollectionTrend()}${renderReminders()}<div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Quick actions</h2><p>Common tasks, right at your fingertips</p></div></div><div class="quick-grid"><button class="quick-action" data-action="add-student"><span class="stat-icon">＋</span><span><strong>Add student</strong><small>Create a student profile</small></span></button><button class="quick-action" data-action="mark-attendance"><span class="stat-icon green">✓</span><span><strong>Mark attendance</strong><small>Record today’s attendance</small></span></button><button class="quick-action" data-action="add-payment"><span class="stat-icon purple">₹</span><span><strong>Record fee payment</strong><small>Save a payment & receipt</small></span></button><button class="quick-action" data-action="add-work"><span class="stat-icon amber">✎</span><span><strong>Add homework / test</strong><small>Plan learning activities</small></span></button></div><div class="panel-head spacer-top"><div><h2>Recent fee payments</h2><p>Your latest recorded transactions</p></div><button class="text-link" data-page="fees">View all →</button></div>${recent.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>STUDENT</th><th>AMOUNT</th><th>DATE</th><th>STATUS</th></tr></thead><tbody>${recent.map(p=>`<tr><td><div class="person-cell">${initialsAvatar(studentName(p.student_id))}<strong>${esc(studentName(p.student_id))}</strong></div></td><td><strong>${money(p.amount)}</strong></td><td>${dateLabel(p.paid_on)}</td><td><span class="badge green">${String(p.method||"cash").toLowerCase()==="online"?"Online received":"Cash received"}</span></td></tr>`).join("")}</tbody></table></div>`:empty("No payments yet","When you record a cash fee, your latest payments will appear here.","add-payment","Record first payment")}</section><section class="panel"><div class="panel-head"><div><h2>Get started</h2><p>Set up your tuition workspace</p></div></div><div class="settings-list"><div class="settings-row"><div><strong>Add your students</strong><p>Build your student register.</p></div><button class="btn btn-outline btn-sm" data-action="add-student">Add</button></div><div class="settings-row"><div><strong>Record attendance</strong><p>Keep a daily attendance log.</p></div><button class="btn btn-outline btn-sm" data-action="mark-attendance">Open</button></div><div class="settings-row"><div><strong>Track fee payments</strong><p>Log payments and print receipts.</p></div><button class="btn btn-outline btn-sm" data-action="add-payment">Add</button></div><div class="settings-row"><div><strong>Set up classes</strong><p>Organise subjects and batches.</p></div><button class="btn btn-outline btn-sm" data-page="classes">Open</button></div></div><div class="notice spacer-top"><strong>Privacy first.</strong> Each teacher account can access only its own tuition records. Keep your login details private.</div></section></div>`}
function renderStudents(){return `${pageHeader("Students","Manage student profiles and their tuition details.",btn("＋ Add student","add-student"))}<section class="panel"><div class="toolbar"><div class="search-box"><span>⌕</span><input id="studentSearch" placeholder="Search by student name, ID or class…"></div><select id="studentClassFilter" class="select-control"><option value="">All classes</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}">Class ${i+1}</option>`).join("")}</select></div><div id="studentsTable">${studentsTable(state.students)}</div></section>`}
function renderReminders(){const due=state.students.filter(s=>s.active&&studentDue(s)>0).sort((a,b)=>studentDue(b)-studentDue(a)).slice(0,5);const unfinished=state.work.filter(w=>!w.completed).slice(0,4);return `<section class="panel smart-reminders"><div class="panel-head"><div><h2>🔔 Smart reminders</h2><p>Quick view of items that may need your attention</p></div><span class="badge amber">${due.length+unfinished.length} items</span></div><div class="reminder-grid"><div class="reminder-tile reminder-fees"><span class="reminder-emoji">₹</span><div><strong>${due.length} fee follow-up${due.length===1?"":"s"}</strong><p>${due.length?`${money(due.reduce((n,s)=>n+studentDue(s),0))} pending among top students`:"No pending fees for active students"}</p></div><button class="btn btn-outline btn-sm" data-page="fees">View fees</button></div><div class="reminder-tile reminder-work"><span class="reminder-emoji">✎</span><div><strong>${unfinished.length} upcoming task${unfinished.length===1?"":"s"}</strong><p>${unfinished.length?unfinished.map(w=>esc(w.title)).join(" · "):"No unfinished homework or tests"}</p></div><button class="btn btn-outline btn-sm" data-page="work">View tasks</button></div></div><p class="field-hint">These are in-app reminders shown when you open the dashboard; they do not send automatic SMS or email.</p></section>`}
function studentsTable(rows){if(!rows.length)return empty("No students added yet","Add your first student to start tracking attendance and fees.","add-student","Add student");return `<div class="table-wrap"><table class="data-table"><thead><tr><th>STUDENT</th><th>STUDENT ID</th><th>CLASS</th><th>MONTHLY FEE</th><th>STATUS</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><div class="person-cell">${initialsAvatar(s.full_name)}<div><strong>${esc(s.full_name)}</strong><small>${esc(s.guardian_phone||"No guardian phone")}</small></div></div></td><td>${esc(s.student_code||"—")}</td><td>Class ${esc(s.class_level)}</td><td>${money(s.monthly_fee)}</td><td><span class="badge ${s.active?"green":"red"}">${s.active?"Active":"Inactive"}</span></td><td><button class="text-link" data-action="edit-student" data-id="${s.id}">Edit</button></td></tr>`).join("")}</tbody></table></div>`}
function renderAttendance(){const date=state.attendanceDate;const rows=state.students.filter(s=>s.active);const existing=state.attendance.filter(a=>a.attendance_date===date);if(!state.attendanceCalendarStudent&&rows.length)state.attendanceCalendarStudent=rows[0].id;const selected=state.students.find(s=>s.id===state.attendanceCalendarStudent)||rows[0];const [yy,mm]=state.attendanceCalendarMonth.split("-").map(Number);const first=new Date(yy,mm-1,1);const days=new Date(yy,mm,0).getDate();const offset=(first.getDay()+6)%7;const monthRecords=state.attendance.filter(a=>a.student_id===selected?.id&&a.attendance_date?.slice(0,7)===state.attendanceCalendarMonth);const cells=Array.from({length:offset},()=>'<div class="attendance-cal-empty"></div>');for(let d=1;d<=days;d++){const iso=`${state.attendanceCalendarMonth}-${String(d).padStart(2,"0")}`;const rec=monthRecords.find(a=>a.attendance_date===iso);const status=rec?.status||"unmarked";cells.push(`<button type="button" class="attendance-cal-day ${status}" data-calendar-date="${iso}" title="${dateLabel(iso)}: ${status==='unmarked'?'Not marked':status}"><span>${d}</span><small>${status==='present'?'P':status==='absent'?'A':status==='leave'?'L':'·'}</small></button>`)}return `${pageHeader("Attendance","Mark daily attendance and review the full month calendar.",`<button class="btn btn-outline" data-action="attendance-date">▦ ${dateLabel(date)}</button><button class="btn btn-primary" data-action="save-attendance">Save attendance</button>`)}<section class="panel attendance-calendar-panel"><div class="panel-head"><div><h2>Monthly attendance calendar</h2><p>Green = Present · Red = Absent · Amber = Leave · Grey = Not marked</p></div></div><div class="attendance-calendar-toolbar"><select id="attendanceCalendarStudent" class="select-control" aria-label="Choose student">${rows.map(s=>`<option value="${s.id}" ${s.id===selected?.id?"selected":""}>${esc(s.full_name)} · Class ${esc(s.class_level)}</option>`).join("")}</select><div class="attendance-month-controls"><button class="btn btn-outline btn-sm" data-action="attendance-month-prev" aria-label="Previous month">‹</button><strong>${monthLabel(state.attendanceCalendarMonth)}</strong><button class="btn btn-outline btn-sm" data-action="attendance-month-next" aria-label="Next month">›</button></div></div>${selected?`<div class="attendance-weekdays">${["Mon","Tue","Wed","Thu","Fri","Sat","Sun"].map(x=>`<span>${x}</span>`).join("")}</div><div class="attendance-calendar-grid">${cells.join("")}</div><div class="attendance-calendar-legend"><span><i class="present"></i>Present</span><span><i class="absent"></i>Absent</span><span><i class="leave"></i>Leave</span><span><i class="unmarked"></i>Not marked</span></div>`:empty("No students yet","Add students to see their monthly attendance calendar.","add-student","Add student")}</section><section class="panel spacer-top"><div class="panel-head"><div><h2>Daily register</h2><p>${dateLabel(date)} · ${rows.length} active students</p></div><span class="badge blue">${existing.length} marked</span></div>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>STUDENT</th><th>CLASS</th><th>STATUS</th></tr></thead><tbody>${rows.map(s=>{const r=existing.find(a=>a.student_id===s.id);const status=r?.status||"";return `<tr data-student-row="${s.id}"><td><div class="person-cell">${initialsAvatar(s.full_name)}<strong>${esc(s.full_name)}</strong></div></td><td>Class ${esc(s.class_level)}</td><td><div class="attendance-actions"><button data-attend="${s.id}" data-status="present" class="${status==="present"?"selected-present":""}">Present</button><button data-attend="${s.id}" data-status="absent" class="${status==="absent"?"selected-absent":""}">Absent</button><button data-attend="${s.id}" data-status="leave" class="${status==="leave"?"selected-leave":""}">Leave</button></div></td></tr>`}).join("")}</tbody></table></div>`:empty("No active students","Add students before marking attendance.","add-student","Add student")}</section>`}
function renderFees(){const month=monthlyPayments(),collected=paymentTotal(month),pending=state.students.reduce((n,s)=>n+studentDue(s),0);return `${pageHeader("Fees & Payments","Record cash or online payments, track dues and issue receipts.",btn("＋ Record fee payment","add-payment"))}<div class="report-cards"><div class="report-box"><span>Collected · ${monthLabel(state.month)}</span><strong>${money(collected)}</strong></div><div class="report-box"><span>Pending · Current month</span><strong>${money(pending)}</strong></div><div class="report-box"><span>Recorded payments</span><strong>${state.payments.length}</strong></div></div><section class="panel"><div class="toolbar"><div class="search-box"><span>⌕</span><input id="feeSearch" placeholder="Search student or receipt number…"></div><input id="feeMonth" class="select-control filter-date" type="month" value="${state.month}"></div><div id="feesTable">${feesTable(month)}</div></section><section class="panel spacer-top"><div class="panel-head"><div><h2>Students with pending fees</h2><p>Monthly fee less recorded payments for the selected month</p></div></div>${pendingTable()}</section>`}
function feesTable(rows){if(!rows.length)return empty("No payments for this month","Record a cash or online payment to start your fee history.","add-payment","Record payment");return `<div class="table-wrap"><table class="data-table"><thead><tr><th>RECEIPT</th><th>STUDENT</th><th>FEE MONTH</th><th>AMOUNT</th><th>PAID ON</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.receipt_no||"—")}</td><td><div class="person-cell">${initialsAvatar(studentName(p.student_id))}<strong>${esc(studentName(p.student_id))}</strong></div></td><td>${monthLabel(p.fee_month)}</td><td><strong>${money(p.amount)}</strong></td><td>${dateLabel(p.paid_on)}</td><td><button class="text-link" data-action="receipt" data-id="${p.id}">Receipt</button></td></tr>`).join("")}</tbody></table></div>`}
function pendingTable(){const rows=state.students.filter(s=>s.active&&studentDue(s)>0);if(!rows.length)return `<div class="empty-state"><div class="empty-icon">✓</div><strong>No pending fees found</strong><p>All current-month fees are covered, or no monthly fee is set.</p></div>`;return `<div class="table-wrap"><table class="data-table"><thead><tr><th>STUDENT</th><th>CLASS</th><th>MONTHLY FEE</th><th>PAID</th><th>DUE</th><th></th></tr></thead><tbody>${rows.map(s=>{const paid=state.payments.filter(p=>p.student_id===s.id&&p.fee_month===state.month).reduce((n,p)=>n+Number(p.amount||0),0);return `<tr><td><strong>${esc(s.full_name)}</strong></td><td>Class ${esc(s.class_level)}</td><td>${money(s.monthly_fee)}</td><td>${money(paid)}</td><td><span class="badge amber">${money(studentDue(s))}</span></td><td><button class="text-link" data-action="add-payment" data-id="${s.id}">Collect</button></td></tr>`}).join("")}</tbody></table></div>`}
function renderClasses(){const rows=state.classes;return `${pageHeader("Classes & Timetable","Organise classes, subjects, batches and weekly timings.",btn("＋ Add class","add-class"))}<section class="panel">${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>CLASS / BATCH</th><th>SUBJECT</th><th>DAY</th><th>TIME</th><th>ROOM</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.subject||"—")}</td><td>${esc(c.day_of_week||"—")}</td><td>${esc(c.start_time||"—")}${c.end_time?" – "+esc(c.end_time):""}</td><td>${esc(c.room||"—")}</td><td><button class="text-link" data-action="edit-class" data-id="${c.id}">Edit</button></td></tr>`).join("")}</tbody></table></div>`:empty("No classes scheduled","Create your first class or batch and add its timing.","add-class","Add class")}</section>`}
function renderWork(){const rows=state.work;return `${pageHeader("Homework & Tests","Plan homework, tests and record student marks.",btn("＋ Add homework / test","add-work"))}<section class="panel">${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>TITLE</th><th>TYPE</th><th>CLASS</th><th>DUE DATE</th><th>MAX MARKS</th><th></th></tr></thead><tbody>${rows.map(w=>`<tr><td><strong>${esc(w.title)}</strong><small class="muted" style="display:block;margin-top:4px">${esc(w.subject||"")}</small></td><td><span class="badge blue">${esc(w.kind)}</span></td><td>${w.class_level?`Class ${esc(w.class_level)}`:"All classes"}</td><td>${dateLabel(w.due_date)}</td><td>${w.max_marks??"—"}</td><td><button class="text-link" data-action="edit-work" data-id="${w.id}">Edit</button></td></tr>`).join("")}</tbody></table></div>`:empty("Nothing planned yet","Add homework or schedule a test for your students.","add-work","Add homework / test")}</section><div class="notice spacer-top">This starter version stores homework and test details. Individual student marks entry and report-card generation can be added in the next implementation pass.</div>`}
function renderReports(){const monthRows=state.payments.filter(p=>p.fee_month===state.month),collected=paymentTotal(monthRows),cash=paymentTotal(monthRows.filter(p=>String(p.method||"cash").toLowerCase()==="cash")),online=paymentTotal(monthRows.filter(p=>String(p.method||"").toLowerCase()==="online")),pendingRows=state.students.filter(s=>s.active).map(s=>{const paid=monthRows.filter(p=>p.student_id===s.id).reduce((n,p)=>n+Number(p.amount||0),0);const fee=Number(s.monthly_fee||0);return {s,paid,due:Math.max(0,fee-paid),status:paid<=0?"Unpaid":paid<fee?"Partial":"Paid"}}),pending=pendingRows.reduce((n,r)=>n+r.due,0),present=state.attendance.filter(a=>a.status==="present"&&a.attendance_date?.slice(0,7)===state.month).length;return `${pageHeader("Reports","Monthly income, payment methods, fee status and reminders.",`<button class="btn btn-outline" data-action="export-csv">↓ Export CSV</button><button class="btn btn-primary" data-action="print">Print report</button>`)}<div class="toolbar"><label class="field-label" for="reportMonth">Report month</label><input id="reportMonth" type="month" class="select-control" value="${state.month}"></div><div class="report-cards"><div class="report-box"><span>Total income · ${monthLabel(state.month)}</span><strong>${money(collected)}</strong></div><div class="report-box"><span>Cash collected</span><strong>${money(cash)}</strong></div><div class="report-box"><span>Online / UPI collected</span><strong>${money(online)}</strong></div><div class="report-box"><span>Outstanding for selected month</span><strong>${money(pending)}</strong></div></div><section class="panel spacer-top"><div class="panel-head"><div><h2>Monthly fee status</h2><p>Paid, partially paid and unpaid students for ${monthLabel(state.month)}.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>STUDENT</th><th>MONTHLY FEE</th><th>COLLECTED</th><th>DUE</th><th>STATUS</th><th>REMINDER</th></tr></thead><tbody>${pendingRows.map(({s,paid,due,status})=>`<tr><td><strong>${esc(s.full_name)}</strong><small class="muted" style="display:block">Class ${esc(s.class_level)}</small></td><td>${money(s.monthly_fee)}</td><td>${money(paid)}</td><td>${money(due)}</td><td><span class="badge ${status==="Paid"?"green":status==="Partial"?"amber":"red"}">${status}</span></td><td>${due>0?`<button class="text-link" data-action="fee-reminder" data-id="${s.id}">WhatsApp reminder</button>`:"—"}</td></tr>`).join("")||`<tr><td colspan="6">No students added yet.</td></tr>`}</tbody></table></div></section><div class="content-grid spacer-top"><section class="panel"><div class="panel-head"><div><h2>Income breakdown</h2><p>Recorded payments by method</p></div></div><div class="settings-list"><div class="settings-row"><div><strong>Cash</strong><p>Payments recorded as cash</p></div><strong>${money(cash)}</strong></div><div class="settings-row"><div><strong>Online / UPI</strong><p>Payments recorded as online</p></div><strong>${money(online)}</strong></div><div class="settings-row"><div><strong>Total received</strong><p>${monthRows.length} payment records</p></div><strong>${money(collected)}</strong></div></div></section><section class="panel"><div class="panel-head"><div><h2>Attendance overview</h2><p>Present marks during ${monthLabel(state.month)}</p></div></div><div class="stat-value">${present}</div><p class="page-subtitle">Saved attendance entries for the selected month.</p><div class="notice spacer-top">Fee status is based on the monthly fee and payments recorded for this selected month. Past months are available by changing the month above.</div></section></div>`}
function sendFeeReminder(studentId){const s=state.students.find(x=>x.id===studentId);if(!s){toast("Student not found.",true);return}const phone=String(s.guardian_phone||"").replace(/\D/g,"");if(!phone){toast("Guardian phone number is not saved for this student.",true);return}const paid=state.payments.filter(p=>p.student_id===s.id&&p.fee_month===state.month).reduce((n,p)=>n+Number(p.amount||0),0);const due=Math.max(0,Number(s.monthly_fee||0)-paid);if(!due){toast("No pending fee for this month.");return}const msg=`Namaste, ${s.full_name} ki ${monthLabel(state.month)} tuition fee mein ₹${due} pending hai. Kripya suvidha anusar payment kar dein. - ${state.profile.tuition_name||"Tuition"}`;const intl=phone.length===10?"91"+phone:phone;window.open(`https://wa.me/${intl}?text=${encodeURIComponent(msg)}`,"_blank","noopener");}
function renderSettings(){return `${pageHeader("Settings","Manage your tuition profile, online fee QR and account.",btn("✎ Edit tuition name","edit-tuition",false))}<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Tuition profile</h2><p>Details shown in your workspace and receipts</p></div></div><div class="settings-list"><div class="settings-row"><div><strong>Tuition name</strong><p>${esc(state.profile.tuition_name||"Not set")}</p></div><button class="btn btn-outline btn-sm" data-action="edit-tuition">Edit</button></div><div class="settings-row"><div><strong>Teacher name</strong><p>${esc(state.profile.full_name||state.user.user_metadata?.full_name||"Teacher")}</p></div></div><div class="settings-row"><div><strong>Registered email</strong><p>${esc(state.user.email||"")}</p></div></div><div class="settings-row"><div><strong>Account created</strong><p>${dateLabel((state.user.created_at||"").slice(0,10))}</p></div></div></div></section><section class="panel"><div class="panel-head"><div><h2>Online fee QR code</h2><p>Students can scan this when you select Online at fee collection.</p></div></div><div class="qr-settings-preview">${state.profile.payment_qr_data?`<img src="${state.profile.payment_qr_data}" alt="Uploaded fee payment QR code">`:`<div class="qr-empty"><span>▦</span><strong>No QR code uploaded</strong><small>Upload your UPI/payment QR to enable online fee display.</small></div>`}</div><form id="paymentQrForm" class="qr-upload-form"><label class="field-label" for="paymentQrFile">Upload QR image</label><input id="paymentQrFile" name="payment_qr" type="file" accept="image/png,image/jpeg,image/webp" required><p class="field-hint">PNG, JPG or WebP · up to 5 MB. The image is compressed before saving.</p><div class="qr-settings-actions"><button class="btn btn-primary" type="submit">Save QR code</button>${state.profile.payment_qr_data?`<button class="btn btn-outline" type="button" id="removePaymentQr">Remove QR</button>`:""}</div></form></section><section class="panel"><div class="panel-head"><div><h2>Security & data</h2><p>Keep your account safe</p></div></div><div class="settings-list"><div class="settings-row"><div><strong>Change password</strong><p>Receive a password reset email.</p></div><button class="btn btn-outline btn-sm" data-action="change-password">Reset</button></div><div class="settings-row"><div><strong>Export your records</strong><p>Download student and payment records as CSV.</p></div><button class="btn btn-outline btn-sm" data-action="export-csv">Export</button></div><div class="settings-row"><div><strong>Full data backup</strong><p>Download a JSON backup of currently loaded tuition records. Store it privately.</p></div><button class="btn btn-outline btn-sm" data-action="backup-json">Backup</button></div><div class="settings-row"><div><strong>Security checklist</strong><p>Use a unique password, sign out on shared devices, and keep Supabase row-level security enabled.</p></div><span class="badge green">Guidance</span></div><div class="settings-row"><div><strong>Print current page</strong><p>Print a report or register.</p></div><button class="btn btn-outline btn-sm" data-action="print">Print</button></div><div class="settings-row"><div><strong>Sign out</strong><p>End this session on this device.</p></div><button class="btn btn-danger btn-sm" data-action="logout">Log out</button></div></div></section></div><div class="notice spacer-top"><strong>Account privacy:</strong> QR code and tuition records are saved to this teacher profile. Supabase row-level security should be enabled using the SQL setup file before using real student data.</div>`}
function wirePageActions(){
  $$("[data-page]",$("#pageContent")).forEach(b=>b.addEventListener("click",()=>navigate(b.dataset.page)));
  $$("[data-action]",$("#pageContent")).forEach(b=>b.addEventListener("click",()=>handleAction(b.dataset.action,b.dataset.id)));
  $("#studentSearch")?.addEventListener("input",filterStudents);
  $("#paymentQrForm")?.addEventListener("submit",savePaymentQr);
  $("#removePaymentQr")?.addEventListener("click",removePaymentQr);$("#studentClassFilter")?.addEventListener("change",filterStudents);
  $("#feeSearch")?.addEventListener("input",filterFees);$("#feeMonth")?.addEventListener("change",ev=>{state.month=ev.target.value||state.month;renderPage()});
  $("#reportMonth")?.addEventListener("change",ev=>{state.month=ev.target.value||state.month;renderPage()});
  $("#attendanceCalendarStudent")?.addEventListener("change",ev=>{state.attendanceCalendarStudent=ev.target.value;renderPage()});
  $$ ("[data-calendar-date]").forEach(b=>b.addEventListener("click",()=>{state.attendanceDate=b.dataset.calendarDate;renderPage();window.scrollTo({top:document.querySelector(".attendance-calendar-panel")?.offsetTop||0,behavior:"smooth"})}));
  $$("[data-attend]").forEach(b=>b.addEventListener("click",()=>{const id=b.dataset.attend,status=b.dataset.status;const row=b.closest("tr");row.querySelectorAll("[data-attend]").forEach(x=>x.classList.remove("selected-present","selected-absent","selected-leave"));b.classList.add(status==="present"?"selected-present":status==="absent"?"selected-absent":"selected-leave");b.dataset.chosen=status;row.dataset.chosen=status}));
}
function filterStudents(){const q=($("#studentSearch")?.value||"").toLowerCase(),cl=$("#studentClassFilter")?.value||"";const rows=state.students.filter(s=>(`${s.full_name} ${s.student_code||""} ${s.class_level}`.toLowerCase().includes(q))&&(!cl||String(s.class_level)===cl));$("#studentsTable").innerHTML=studentsTable(rows);$$("[data-action]",$("#studentsTable")).forEach(b=>b.addEventListener("click",()=>handleAction(b.dataset.action,b.dataset.id)))}
function filterFees(){const q=($("#feeSearch")?.value||"").toLowerCase();const rows=monthlyPayments().filter(p=>(`${studentName(p.student_id)} ${p.receipt_no||""}`.toLowerCase().includes(q)));$("#feesTable").innerHTML=feesTable(rows);$$("[data-action]",$("#feesTable")).forEach(b=>b.addEventListener("click",()=>handleAction(b.dataset.action,b.dataset.id)))}
async function handleAction(action,id){switch(action){case"add-student":openStudentEditor();break;case"edit-student":openStudentEditor(id);break;case"add-payment":openPaymentEditor(id);break;case"receipt":showReceipt(id);break;case"fee-reminder":sendFeeReminder(id);break;case"mark-attendance":navigate("attendance");break;case"save-attendance":saveAttendance();break;case"attendance-date":openDatePicker();break;case"attendance-month-prev":state.attendanceCalendarMonth=shiftMonth(state.attendanceCalendarMonth,-1);renderPage();break;case"attendance-month-next":state.attendanceCalendarMonth=shiftMonth(state.attendanceCalendarMonth,1);renderPage();break;case"add-class":openClassEditor();break;case"edit-class":openClassEditor(id);break;case"add-work":openWorkEditor();break;case"edit-work":openWorkEditor(id);break;case"edit-tuition":case"editTuition":openTuitionEditor();break;case"change-password":state.otpPurpose="reset";showAuth("reset");$("#resetEmail").value=state.user.email||"";$("#appShell").classList.add("hidden");$("#authScreen").classList.remove("hidden");break;case"export-csv":exportCsv();break;case"backup-json":exportJsonBackup();break;case"print":window.print();break;case"logout":logout();break;default:break}}
function openModal(title,eyebrow,body){$("#modalTitle").textContent=title;$("#modalEyebrow").textContent=eyebrow;$("#modalBody").innerHTML=body;$("#modal").showModal()}
function closeModal(){if($("#modal").open)$("#modal").close()}
function studentOptions(selected=""){return `<option value="">Select student</option>${state.students.filter(s=>s.active).map(s=>`<option value="${s.id}" ${s.id===selected?"selected":""}>${esc(s.full_name)} · Class ${esc(s.class_level)}</option>`).join("")}`}
function openStudentEditor(id){const s=state.students.find(x=>x.id===id)||{};openModal(id?"Edit student":"Add student","STUDENT DETAILS",`<form id="studentForm" class="modal-form"><div class="form-field full"><label>Student full name *</label><input name="full_name" required maxlength="120" value="${esc(s.full_name||"")}" placeholder="Enter student name"></div><div class="form-field"><label>Class *</label><select name="class_level" required>${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${String(s.class_level||"")===String(i+1)?"selected":""}>Class ${i+1}</option>`).join("")}</select></div><div class="form-field"><label>Monthly fee (₹)</label><input name="monthly_fee" type="number" min="0" step="1" value="${Number(s.monthly_fee||0)}"></div><div class="form-field"><label>Guardian name</label><input name="guardian_name" maxlength="120" value="${esc(s.guardian_name||"")}"></div><div class="form-field"><label>Guardian phone</label><input name="guardian_phone" inputmode="numeric" maxlength="15" value="${esc(s.guardian_phone||"")}"></div><div class="form-field full"><label>School (optional)</label><input name="school" maxlength="160" value="${esc(s.school||"")}"></div><div class="form-field full"><label><input name="active" type="checkbox" style="width:auto;margin-right:7px" ${s.active===false?"":"checked"}> Student is active</label></div><div class="modal-actions"><button type="button" class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary" type="submit">${id?"Save changes":"Add student"}</button></div></form>`);$("#studentForm").addEventListener("submit",ev=>saveStudent(ev,id));$$("[data-close]").forEach(b=>b.addEventListener("click",closeModal))}
async function saveStudent(ev,id){ev.preventDefault();const f=new FormData(ev.target),payload={full_name:String(f.get("full_name")).trim(),class_level:Number(f.get("class_level")),monthly_fee:Number(f.get("monthly_fee")||0),guardian_name:String(f.get("guardian_name")||"").trim(),guardian_phone:String(f.get("guardian_phone")||"").trim(),school:String(f.get("school")||"").trim(),active:f.get("active")==="on"};if(id){const {error}=await state.supabase.from("students").update(payload).eq("id",id);if(error){toast(error.message,true);return}}else{payload.student_code="STU-"+Math.random().toString(36).slice(2,8).toUpperCase();const {error}=await state.supabase.from("students").insert(payload);if(error){toast(error.message,true);return}}closeModal();toast(id?"Student updated.":"Student added.");await refresh()}
function openPaymentEditor(studentId=""){if(!state.students.filter(s=>s.active).length){toast("Add a student before recording fees.",true);return}openModal("Record fee payment","FEES & PAYMENTS",`<form id="paymentForm" class="modal-form"><div class="form-field full"><label>Student *</label><select name="student_id" required>${studentOptions(studentId)}</select></div><div class="form-field"><label>Amount received (₹) *</label><input name="amount" type="number" min="1" step="1" required placeholder="e.g. 1000"></div><div class="form-field"><label>Payment date *</label><input name="paid_on" type="date" required value="${todayISO()}"></div><div class="form-field full"><label>Fee month *</label><input name="fee_month" type="month" required value="${state.month}"></div><div class="form-field full"><label>Payment method *</label><div class="payment-method-options"><label><input type="radio" name="method" value="cash" checked> <span>💵 Cash</span></label><label><input type="radio" name="method" value="online"> <span>📱 Online / UPI</span></label></div></div><div class="form-field full hidden" id="onlineQrPanel">${state.profile.payment_qr_data?`<div class="online-qr-card"><strong>Scan QR to pay</strong><img src="${state.profile.payment_qr_data}" alt="Tuition payment QR code"><p>Ask the student to scan this QR using their UPI app. Verify the payment in your bank/UPI app before saving.</p></div><label class="payment-confirm"><input type="checkbox" name="online_confirm" id="onlinePaymentConfirm"> I have verified that the payment was received.</label>`:`<div class="notice"><strong>QR code not set up.</strong> Upload your payment QR in Settings before recording an online payment.</div><button type="button" class="btn btn-outline" id="goToQrSettings">Open Settings</button>`}</div><div class="form-field full"><label>Notes (optional)</label><input name="notes" maxlength="200" placeholder="e.g. Monthly tuition fee"></div><div class="modal-actions"><button type="button" class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary" type="submit">Save payment</button></div></form>`);const form=$("#paymentForm");form.addEventListener("submit",savePayment);form.querySelectorAll('input[name="method"]').forEach(r=>r.addEventListener("change",()=>{const online=r.value==="online"&&r.checked;$("#onlineQrPanel")?.classList.toggle("hidden",!online);const submit=form.querySelector('button[type="submit"]');if(submit)submit.textContent=online?"Confirm & save online payment":"Save cash payment"}));$("#goToQrSettings")?.addEventListener("click",()=>{closeModal();navigate("settings")});$$("[data-close]").forEach(b=>b.addEventListener("click",closeModal))}
async function savePayment(ev){ev.preventDefault();const form=ev.currentTarget;if(form.dataset.saving==="true")return;const f=new FormData(form),studentId=String(f.get("student_id")),amount=Number(f.get("amount")),paidOn=String(f.get("paid_on")),feeMonth=String(f.get("fee_month")),method=String(f.get("method")||"cash");if(!studentId||!Number.isFinite(amount)||amount<=0||!paidOn||!feeMonth){toast("Check the required payment details.",true);return}if(method==="online"&&!state.profile.payment_qr_data){toast("Upload a payment QR code in Settings first.",true);return}if(method==="online"&&!f.get("online_confirm")){toast("Please verify the payment in your UPI/bank app before saving.",true);return}form.dataset.saving="true";const submit=form.querySelector("button[type=submit]");setBusy(submit,true,"Saving payment…");try{const receipt="RCPT-"+Date.now().toString().slice(-9);const {data,error}=await state.supabase.from("fee_payments").insert({student_id:studentId,amount,paid_on:paidOn,fee_month:feeMonth,method,notes:String(f.get("notes")||"").trim(),receipt_no:receipt}).select().single();if(error)throw error;closeModal();state.month=feeMonth;await refresh();toast(`${method==="online"?"Online":"Cash"} payment saved. Receipt ${receipt}`);showReceipt(data.id)}catch(e){toast(e.message||"Payment could not be saved.",true)}finally{form.dataset.saving="false";setBusy(submit,false)}}
async function savePaymentQr(ev){ev.preventDefault();const form=ev.currentTarget,file=$("#paymentQrFile")?.files?.[0];if(!file)return;if(!["image/png","image/jpeg","image/webp"].includes(file.type)){toast("Choose a PNG, JPG or WebP image.",true);return}if(file.size>5*1024*1024){toast("QR image must be smaller than 5 MB.",true);return}const submit=form.querySelector('button[type="submit"]');setBusy(submit,true,"Compressing & saving…");try{const dataUrl=await compressQrImage(file);const {error}=await state.supabase.from("teacher_profiles").update({payment_qr_data:dataUrl,updated_at:new Date().toISOString()}).eq("id",state.user.id);if(error)throw error;state.profile={...state.profile,payment_qr_data:dataUrl};toast("Payment QR code saved. It will appear for online payments.");renderPage()}catch(e){toast(e.message||"Could not save QR code.",true)}finally{setBusy(submit,false)}}
function compressQrImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error("Could not read that image."));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error("That image could not be opened."));img.onload=()=>{const scale=Math.min(1,1000/Math.max(img.width,img.height));const canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL("image/png");if(data.length>700000)reject(new Error("QR image is still too large. Please upload a smaller/cropped image."));else resolve(data)};img.src=String(reader.result)};reader.readAsDataURL(file)})}
async function removePaymentQr(){if(!confirm("Remove the saved online payment QR code?"))return;const {error}=await state.supabase.from("teacher_profiles").update({payment_qr_data:null,updated_at:new Date().toISOString()}).eq("id",state.user.id);if(error){toast(error.message,true);return}state.profile={...state.profile,payment_qr_data:null};toast("Payment QR removed.");renderPage()}
function receiptText(p,s){return `${state.profile.tuition_name}\nFEE RECEIPT\nPayment received · ${String(p.method||"cash").toLowerCase()==="online"?"Online / UPI":"Cash"}\n\nReceipt no.: ${p.receipt_no||"—"}\nStudent: ${s.full_name||"—"}\nClass: ${s.class_level||"—"}\nFee month: ${monthLabel(p.fee_month)}\nPayment date: ${dateLabel(p.paid_on)}\nAmount received: ${money(p.amount)}\n\nThank you · ${state.profile.tuition_name}\nComputer-generated receipt`}
function showReceipt(id){const p=state.payments.find(x=>x.id===id);if(!p){toast("Receipt not found.",true);return}const s=state.students.find(x=>x.id===p.student_id)||{};const details=receiptText(p,s);openModal("Payment receipt","PAYMENT SAVED",`<div class="receipt-preview"><div class="receipt-brand">${esc(state.profile.tuition_name)}</div><h3>Fee receipt</h3><p class="muted">Payment received · ${String(p.method||"cash").toLowerCase()==="online"?"Online / UPI":"Cash"}</p><div class="receipt-preview-line"></div><div class="receipt-preview-row"><span>Receipt no.</span><strong>${esc(p.receipt_no||"—")}</strong></div><div class="receipt-preview-row"><span>Student</span><strong>${esc(s.full_name||"—")}</strong></div><div class="receipt-preview-row"><span>Class</span><strong>${esc(s.class_level||"—")}</strong></div><div class="receipt-preview-row"><span>Fee month</span><strong>${esc(monthLabel(p.fee_month))}</strong></div><div class="receipt-preview-row"><span>Payment date</span><strong>${esc(dateLabel(p.paid_on))}</strong></div><div class="receipt-preview-amount">${money(p.amount)}</div><p class="receipt-thanks">Thank you · ${esc(state.profile.tuition_name)}</p></div><div class="receipt-modal-actions"><button type="button" class="btn btn-outline" id="receiptBackBtn">← Back</button><button type="button" class="btn btn-primary" id="receiptDownloadBtn">↓ Download receipt</button></div>`);$("#receiptBackBtn").addEventListener("click",closeModal);$("#receiptDownloadBtn").addEventListener("click",()=>downloadReceipt(details,p.receipt_no||"receipt"))}
function downloadReceipt(content,receiptNo){const rows=String(content).split("\n");const safe=rows.map((line,i)=>i===0?`<h1>${esc(line)}</h1>`:i===1?`<h2>${esc(line)}</h2>`:`<p>${esc(line)||"&nbsp;"}</p>`).join("");const win=window.open("","_blank","width=700,height=800");if(!win){toast("Allow pop-ups to print or save the receipt as PDF.",true);return}win.document.write(`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(receiptNo)} - Fee Receipt</title><style>body{font:15px Arial,sans-serif;color:#17233c;padding:32px;max-width:680px;margin:auto}.receipt{border:1px solid #dbe2ee;border-radius:16px;padding:28px}h1{font-size:22px;color:#14866d;margin:0 0 8px}h2{font-size:18px;margin:0 0 20px}p{white-space:pre-wrap;border-bottom:1px solid #edf0f5;padding:7px 0;margin:0}.actions{display:flex;gap:10px;margin:20px 0}button{padding:10px 15px;border:0;border-radius:8px;background:#14866d;color:#fff;font-weight:bold}@media print{.actions{display:none}body{padding:0}.receipt{border:0}}</style></head><body><div class="receipt">${safe}<div class="actions"><button onclick="window.print()">Print / Save as PDF</button><button onclick="window.close()">Close</button></div></div><script>setTimeout(()=>window.print(),350)<\/script></body></html>`);win.document.close();}
function openDatePicker(){openModal("Select attendance date","ATTENDANCE",`<form id="dateForm" class="modal-form"><div class="form-field full"><label>Date</label><input name="date" type="date" required value="${state.attendanceDate}"></div><div class="modal-actions"><button type="button" class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary">Open register</button></div></form>`);$("#dateForm").addEventListener("submit",ev=>{ev.preventDefault();state.attendanceDate=new FormData(ev.target).get("date");closeModal();renderPage()});$$("[data-close]").forEach(b=>b.addEventListener("click",closeModal))}
async function saveAttendance(){const rows=$$("tr[data-chosen]");const marked=[];rows.forEach(r=>{const b=$("[data-attend][data-chosen]",r);if(b)marked.push({student_id:b.dataset.attend,status:b.dataset.chosen})});if(!marked.length){toast("Mark Present, Absent or Leave for at least one student.",true);return}for(const m of marked){const old=state.attendance.find(a=>a.student_id===m.student_id&&a.attendance_date===state.attendanceDate);let result;if(old)result=await state.supabase.from("attendance_records").update({status:m.status}).eq("id",old.id);else result=await state.supabase.from("attendance_records").insert({student_id:m.student_id,attendance_date:state.attendanceDate,status:m.status});if(result.error){toast(result.error.message,true);return}}toast("Attendance saved.");await refresh()}
function openClassEditor(id){const c=state.classes.find(x=>x.id===id)||{};openModal(id?"Edit class":"Add class","CLASS SCHEDULE",`<form id="classForm" class="modal-form"><div class="form-field full"><label>Class / batch name *</label><input name="name" required maxlength="100" value="${esc(c.name||"")}" placeholder="e.g. Class 10 - Evening"></div><div class="form-field"><label>Subject</label><input name="subject" maxlength="80" value="${esc(c.subject||"")}"></div><div class="form-field"><label>Day</label><select name="day_of_week">${["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"].map(d=>`<option ${c.day_of_week===d?"selected":""}>${d}</option>`).join("")}</select></div><div class="form-field"><label>Start time</label><input name="start_time" type="time" value="${esc(c.start_time||"")}"></div><div class="form-field"><label>End time</label><input name="end_time" type="time" value="${esc(c.end_time||"")}"></div><div class="form-field full"><label>Room / location</label><input name="room" maxlength="100" value="${esc(c.room||"")}"></div><div class="modal-actions"><button type="button" class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary">Save class</button></div></form>`);$("#classForm").addEventListener("submit",async ev=>{ev.preventDefault();const f=new FormData(ev.target),p={name:String(f.get("name")).trim(),subject:String(f.get("subject")||""),day_of_week:String(f.get("day_of_week")||""),start_time:String(f.get("start_time")||null)||null,end_time:String(f.get("end_time")||null)||null,room:String(f.get("room")||"")};const r=id?await state.supabase.from("classes").update(p).eq("id",id):await state.supabase.from("classes").insert(p);if(r.error){toast(r.error.message,true);return}closeModal();toast("Class saved.");await refresh()});$$("[data-close]").forEach(b=>b.addEventListener("click",closeModal))}
function openWorkEditor(id){const w=state.work.find(x=>x.id===id)||{};openModal(id?"Edit homework / test":"Add homework / test","LEARNING",`<form id="workForm" class="modal-form"><div class="form-field full"><label>Title *</label><input name="title" required maxlength="160" value="${esc(w.title||"")}" placeholder="e.g. Chapter 3 maths test"></div><div class="form-field"><label>Type</label><select name="kind"><option ${w.kind==="Homework"?"selected":""}>Homework</option><option ${w.kind==="Test"?"selected":""}>Test</option><option ${w.kind==="Exam"?"selected":""}>Exam</option></select></div><div class="form-field"><label>Class (optional)</label><select name="class_level"><option value="">All classes</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${String(w.class_level||"")===String(i+1)?"selected":""}>Class ${i+1}</option>`).join("")}</select></div><div class="form-field"><label>Subject</label><input name="subject" maxlength="80" value="${esc(w.subject||"")}"></div><div class="form-field"><label>Due date</label><input name="due_date" type="date" value="${esc(w.due_date||"")}"></div><div class="form-field"><label>Maximum marks (tests)</label><input name="max_marks" type="number" min="0" value="${w.max_marks??""}"></div><div class="form-field full"><label>Instructions</label><textarea name="details" maxlength="2000">${esc(w.details||"")}</textarea></div><div class="modal-actions"><button type="button" class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary">Save</button></div></form>`);$("#workForm").addEventListener("submit",async ev=>{ev.preventDefault();const f=new FormData(ev.target),p={title:String(f.get("title")).trim(),kind:String(f.get("kind")),class_level:f.get("class_level")?Number(f.get("class_level")):null,subject:String(f.get("subject")||""),due_date:String(f.get("due_date")||"")||null,max_marks:f.get("max_marks")?Number(f.get("max_marks")):null,details:String(f.get("details")||"")};const r=id?await state.supabase.from("work_items").update(p).eq("id",id):await state.supabase.from("work_items").insert(p);if(r.error){toast(r.error.message,true);return}closeModal();toast("Saved.");await refresh()});$$("[data-close]").forEach(b=>b.addEventListener("click",closeModal))}
function openTuitionEditor(){openModal("Tuition profile","WORKSPACE SETTINGS",`<form id="tuitionEditForm" class="modal-form"><div class="form-field full"><label>Tuition name *</label><input name="tuition_name" maxlength="120" required value="${esc(state.profile.tuition_name||"")}"></div><div class="form-field full"><label>Teacher name</label><input name="full_name" maxlength="80" value="${esc(state.profile.full_name||"")}"></div><div class="modal-actions"><button type="button" class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary">Save profile</button></div></form>`);$("#tuitionEditForm").addEventListener("submit",async ev=>{ev.preventDefault();const f=new FormData(ev.target),p={tuition_name:String(f.get("tuition_name")).trim(),full_name:String(f.get("full_name")).trim(),email:state.user.email,updated_at:new Date().toISOString()};const {error}=await state.supabase.from("teacher_profiles").upsert({id:state.user.id,...p});if(error){toast(error.message,true);return}state.profile={...state.profile,...p};closeModal();syncProfile();renderPage();toast("Tuition profile updated.")});$$("[data-close]").forEach(b=>b.addEventListener("click",closeModal))}
function exportCsv(){const rows=[["Student ID","Student Name","Class","Monthly Fee","Active"],...state.students.map(s=>[s.student_code,s.full_name,s.class_level,s.monthly_fee,s.active])];const feeRows=[["Receipt","Student","Fee Month","Amount","Date","Method"],...state.payments.map(p=>[p.receipt_no,studentName(p.student_id),p.fee_month,p.amount,p.paid_on,p.method])];downloadCsv("students.csv",rows);downloadCsv("fee-payments.csv",feeRows);toast("Student and payment CSV files exported.")}
function exportJsonBackup(){if(!state.user){toast("Sign in before creating a backup.",true);return}const backup={format:"tuition-manager-backup",version:1,created_at:new Date().toISOString(),tuition:{name:state.profile?.tuition_name||"",teacher_email:state.user.email||""},records:{students:state.students,payments:state.payments,attendance:state.attendance,classes:state.classes,work:state.work}};const blob=new Blob([JSON.stringify(backup,null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`tuition-manager-backup-${todayISO()}.json`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast("JSON backup downloaded. Keep it in a private, secure location.")}
function downloadCsv(name,rows){const csv=rows.map(r=>r.map(v=>`"${String(v??"").replace(/"/g,'""')}"`).join(",")).join("\r\n");const blob=new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8;"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function logout(){if(state.supabase)await state.supabase.auth.signOut();state.user=null;state.profile=null;state.students=[];state.payments=[];state.attendance=[];state.classes=[];state.work=[];showAuth("login");toggleSidebar(false)}
document.addEventListener("DOMContentLoaded",init);

// Progressive Web App install support (installable from a secure HTTPS deployment).
let deferredInstallPrompt=null;
window.addEventListener("beforeinstallprompt",(event)=>{event.preventDefault();deferredInstallPrompt=event;const b=document.querySelector("#installAppBtn");if(b){b.hidden=false;b.textContent="＋ Install app"}});
window.addEventListener("appinstalled",()=>{deferredInstallPrompt=null;const b=document.querySelector("#installAppBtn");if(b)b.hidden=true;toast("Tuition Manager installed on this device.")});
document.addEventListener("DOMContentLoaded",()=>{const b=document.querySelector("#installAppBtn");if(b)b.addEventListener("click",async()=>{if(deferredInstallPrompt){deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;b.hidden=true}else{toast("On Android Chrome: open browser menu ⋮ and choose Install app or Add to Home screen.")}});if("serviceWorker" in navigator && location.protocol.startsWith("http")){navigator.serviceWorker.register("./service-worker.js").catch(err=>console.warn("Service worker registration failed",err))}});
